                    simpleExplanation = "👨‍🏫 توضیح و یاد دادن به زبان خودمانی:\n• انواع نواحی از نظر مبادلات تجاری جهانی: به‌طور کلی، در نتیجه فرایندی که تاکنون در اقتصاد جهانی طی شده است، نواحی از نظر نوع غالب مبادلات اقتصادی به دو گروه اصلی تقسیم می‌شوند: ۱. کشورهایی که اقتصاد آنها به‌طور عمده مبتنی بر تولید و صدور مواد اولیه و خام و منابع انرژی و معدنی است؛ اقتصاد کشورهای گروه اول در برابر نوسانات قیمت در بازارهای جهانی آسیب‌پذیری زیادی دارد و کاهش قیمت خرید محصولات آنها می‌تواند شوک‌های عظیمی به اقتصادشان وارد کند؛ در این نوع اقتصاد، حمایت از بخش‌های تولیدی داخلی کم است و واردات گسترش زیادی دارد. ۲. کشورهایی که اقتصاد و درآمد آنها به‌طور عمده مبتنی بر تولید و صدور انواع کالاهای کارخانه‌ای و صنعتی همراه با فناوری‌های پیشرفته و نوین است.\n• اوپک (OPEC): در بین کشورهای صادرکننده مواد خام و منابع انرژی، برخی کشورهای صادرکننده نفت و گاز برای دفاع از منافع خود و جلوگیری از آسیب‌پذیری ناشی از کاهش قیمت نفت در بازار جهانی، با یکدیگر متحد شده و سازمان «اوپک» را به وجود آورده‌اند؛ اوپک یا سازمان کشورهای صادرکننده نفت، یک کارتل بین‌المللی است و در حال حاضر یازده کشور الجزایر، کنگو، گینه استوایی، گابن، ایران، عراق، کویت، لیبی، نیجریه، عربستان سعودی و ونزوئلا عضو آن هستند؛ قطر در ژانویه ۲۰۱۹، اکوادور در ژانویه ۲۰۲۰، آنگولا در ژانویه ۲۰۲۴ و امارات متحده عربی در ۱ مه ۲۰۲۶ (اعلام ۲۸ آوریل ۲۰۲۶) از اوپک خارج شدند. منبع: opec.org؛ رویترز، آوریل ۲۰۲۶. اوپک که هدف آن دفاع از منافع کشورهای صادرکننده نفت است، تلاش می‌کند که کشورهای عضو بتوانند متحد و هماهنگ عمل کنند و نفت را با بهترین قیمت، بفروشند؛ این سازمان در سال ۱۹۶۰ میلادی برای مقابله با سیاست‌های استثماری شرکت‌های بزرگ نفتی امریکا و اروپا به وجود آمد؛ تا آن زمان، این شرکت‌ها فناوری تولید نفت خام و شبکه حمل و نقل آن را در اختیار داشتند و از افزایش قیمت نفت در بازارهای جهانی جلوگیری می‌کردند؛ مقر سازمان اوپک در وین است و کشورهای عضو برای تبادل نظر در موضوعاتی چون تعیین سهمیه فروش نفت، قیمت‌گذاری و نظایر آن با یکدیگر جلسات گفت‌وگو برگزار می‌کنند؛ ساختمان اوپک در وین و اجلاس اوپک در وین، در کتاب آمده است.\n• نابرابری اقتصادی، نابرابری فضایی: ما در جهانی آکنده از نابرابری زندگی می‌کنیم؛ جهانی که در آن تعداد زیادی از مردم مجبور به تحمل فقر و رنج‌اند؛ در جغرافیای پایه نهم با موضوع نابرابری جهانی آشنا شدید و آموختید که یکی از ملاک‌های سنجش و مقایسه کشورها در این زمینه «شاخص توسعه انسانی» است؛ همچنین، دریافتید که شاخص توسعه انسانی سه عامل را در بر می‌گیرد: ۱. درآمد و رفاه، ۲. امید به زندگی یا متوسط طول عمر، ۳. سواد و آموزش؛ عامل اول جنبه اقتصادی دارد؛ امروزه ثروت و درآمد جهان به شدت در دست برخی کشورها متمرکز شده است؛ به‌طوری که مردم برخی از کشورها درآمد و سطح زندگی و رفاه خوبی دارند؛ در حالی که در برخی کشورهای دیگر، بخش بزرگی از مردم با فقر و کمبود امکانات زندگی مواجه‌اند؛ گزارش‌های پژوهشگران درباره وضعیت ثروت و فقر در دنیا نشان می‌دهد که این شکاف هر روز بیشتر می‌شود؛ بر اساس برآورد بانک جهانی، بیش از ۲ میلیارد نفر از مردم جهان روزانه با یک دلار یا کمتر از یک دلار زندگی می‌کنند؛ بر اساس آمار سازمان ملل، صد میلیون نفر از مردم جهان در خیابان‌ها، زیر پل‌ها و گورستان‌ها و نظایر آن می‌خوابند و هیچ نوع مسکن و سرپناهی ندارند؛ در کلکته هند، تعداد زیادی از مردم و از جمله حدود ۲۰۰ هزار کودک در خیابان زندگی می‌کنند؛ درآمد سرانه کشور نروژ ۴۷ برابر درآمد سرانه در کشور اریتره و درآمد سرانه آلمان ۲۵ برابر درآمد سرانه افغانستان است؛ به گزارش آکسفام، ۸۵ نفر از ثروتمندترین افراد جهان هم‌اکنون نیمی از ثروت جهان را در اختیار دارند؛ نمودار توزیع ثروت در جمعیت بزرگسال جهان (گزارش آکسفام ۲۰۱۵ میلادی) این نابرابری را نشان می‌دهد؛ منظور از ثروت، دارایی افراد است نه درآمد؛ ثروت یعنی هر آنچه قابلیت فروش و تبدیل شدن به پول را دارد؛ این اعداد، داده کتاب‌اند و درس حول حفظ کردن آنها ساخته نشده است.\n• نتیجه نابرابری اقتصادی، نابرابری فضایی: نابرابری اقتصادی در فضای جغرافیایی جلوه‌گر می‌شود؛ به عبارت دیگر، چون منابع و امکانات و خدمات به‌طور عادلانه توزیع نمی‌شوند، نابرابری را می‌توان در سطح زمین و فضایی که انسان‌ها در آن زندگی می‌کنند، مشاهده کرد؛ در نتیجه نابرابری اقتصادی، ناحیه‌هایی پدید می‌آیند که از نظر امکانات و تسهیلات و چشم‌اندازهای جغرافیایی با یکدیگر تفاوت دارند؛ چهار تصویر کتاب این را نشان می‌دهد: محله فقیرنشین شهری در کلمبیا، زاغه‌نشینی در اتیوپی، مرکز خرید لی تئاتر در هنگ کنگ و محله ثروتمندنشین در موناکو.\n• مرکز-پیرامون: در نظام سرمایه‌داری جهانی، بر اساس روابط و مبادله نابرابری که بین نواحی پدید آمده است، برخی نواحی نقش «مرکز» یافته و بر سایر نواحی غالب و مسلط شده‌اند؛ برخی نواحی نیز نقش «پیرامون» دارند که به لحاظ اقتصادی به مرکز وابسته‌اند؛ بر اساس این نظریه، مرکز، پیرامون را استثمار می‌کند و بر آن سیطره اقتصادی دارد؛ مرکز: منظور از مرکز، کانون‌های توسعه‌یافته صنعتی است که از نظر درآمد و ثروت بالاترین موقعیت را دارند، مرکز نامیده می‌شوند؛ این کشورها مانند یک قطب آهنربا عمل می‌کنند و بخش عمده‌ای از سود و ثروت جهان را دریافت و جذب می‌کنند؛ آنها حتی به صدور سرمایه، یعنی سرمایه‌گذاری در دیگر نواحی جهان می‌پردازند؛ از ویژگی‌های کشورهای مرکز، برخورداری از صنایع نو و خدمات پیشرفته، فناوری بالا و نیروی ماهر و متخصص، و زیرساخت‌های مناسب برای توسعه اقتصادی مانند حمل و نقل پیشرفته و سطح بالای زندگی و رفاه اجتماعی است؛ کشورهای مرکز، مواد خام را با قیمت ارزان‌تر از کشورهای پیرامون به دست می‌آورند و کالاهای ساخته‌شده صنعتی را با سود بیشتر به آنها می‌فروشند؛ کشورهای مرکز همچنین از طریق سرمایه‌گذاری یا شرکت‌های چندملیتی از نیروی کار ارزان‌قیمت کشورهای پیرامون استفاده می‌کنند؛ کشورهای امریکای شمالی، اروپای غربی، ژاپن و استرالیا جزء کشورهای مرکز هستند؛ کشورهای مرکز گاهی با روش‌های مختلف افراد با استعداد و متخصص یا به اصطلاح، مغزهای متفکر را نیز از کشورهای پیرامون به خود جذب می‌کنند؛ در حالی که کشورهای پیرامون هزینه‌های تحصیل و رشد این افراد را پرداخته‌اند.\n• پیرامون: کشورهای پیرامون عمدتاً تولیدکننده و صادرکننده مواد اولیه و خام‌اند؛ این کشورها از نظر توسعه صنعتی و فناوری‌های نوین در سطح پایین‌تری قرار دارند؛ این کشورها که به واردات کالاهای صنعتی از مرکز وابسته‌اند، بازار خوبی نیز برای تولیدات آنها هستند و بنابراین، سود هنگفتی نصیب کشورهای مرکز می‌کنند؛ از دیگر ویژگی‌های کشورهای پیرامون، کمبود نیروی کار ماهر و متخصص و زیرساخت‌ها و تجهیزات لازم برای توسعه صنعتی است؛ از جمله کشورهای پیرامون در قاره‌های آسیا، افریقا و امریکای لاتین می‌توان به کشورهای افغانستان، بنگلادش، مراکش، نامبیا، پرو و نیکاراگوئه اشاره کرد.\n• نیمه پیرامون: جایگاه کشورها به عنوان مرکز و پیرامون در طول زمان ثابت نیست و ممکن است تغییر کند؛ نظریه‌پردازان مرکز-پیرامون معتقدند که در طول زمان گروهی از کشورها جایگاه نیمه پیرامون یافته‌اند؛ منظور از کشورهای نیمه پیرامون کشورهایی هستند که بین مرکز و پیرامون قرار گرفته‌اند؛ این کشورها از نظر اقتصادی از کشورهای پیرامون قوی‌ترند اما هنوز از نظر قدرت اقتصادی به کشورهای مرکز نرسیده‌اند؛ این کشورها بین کشورهای مرکز و پیرامون نقش واسطه بازی می‌کنند و ساختار اقتصادی و اجتماعی آنها دچار تغییرات و تحولات صنعتی و فناورانه شده است؛ از جمله کشورهای نیمه پیرامون می‌توان به چین، که در دو دهه اخیر خیز اقتصادی فوق‌العاده‌ای در جهان برداشته است و همچنین کره جنوبی و سنگاپور اشاره کرد.\n\n📖 آموزش کامل و پله‌به‌پله مفاهیم این گام:\n• دو گروه نواحی از نظر مبادلات تجاری: گروه اول (صادرکننده مواد اولیه و خام و منابع انرژی و معدنی؛ آسیب‌پذیر در برابر نوسانات قیمت؛ حمایت از بخش‌های تولیدی داخلی کم؛ واردات گسترده) و گروه دوم (صادرکننده کالاهای کارخانه‌ای و صنعتی با فناوری‌های پیشرفته و نوین).\n• اوپک: سازمان کشورهای صادرکننده نفت؛ کارتل بین‌المللی؛ ۱۱ کشور عضو (الجزایر، کنگو، گینه استوایی، گابن، ایران، عراق، کویت، لیبی، نیجریه، عربستان سعودی، ونزوئلا)؛ تأسیس ۱۹۶۰؛ مقر وین؛ هدف: دفاع از منافع کشورهای صادرکننده نفت و فروش نفت با بهترین قیمت. منبع: opec.org.\n• شاخص توسعه انسانی: سه عامل درآمد و رفاه، امید به زندگی (متوسط طول عمر)، سواد و آموزش؛ عامل اول جنبه اقتصادی دارد.\n• نابرابری فضایی: نابرابری اقتصادی در فضای جغرافیایی جلوه‌گر می‌شود؛ محله فقیرنشین کلمبیا، زاغه‌نشینی اتیوپی، مرکز خرید هنگ کنگ، محله ثروتمندنشین موناکو.\n• مرکز-پیرامون: مرکز (امریکای شمالی، اروپای غربی، ژاپن، استرالیا؛ صنایع نو و خدمات پیشرفته، فناوری بالا، نیروی ماهر، زیرساخت مناسب؛ جذب مغزهای متفکر)، پیرامون (افغانستان، بنگلادش، مراکش، نامبیا، پرو، نیکاراگوئه؛ صادرکننده مواد خام؛ کمبود نیروی ماهر و زیرساخت)، نیمه پیرامون (چین، کره جنوبی، سنگاپور؛ بین مرکز و پیرامون؛ نقش واسطه).",
                    visualDiagramText = "┌── جدول مقایسه‌ای درس: دو گروه نواحی و مدل مرکز-پیرامون ──┐\n│ گروه اول (صادرکننده مواد خام) ⬅ اقتصاد مبتنی بر تولید و صدور مواد اولیه و خام و منابع انرژی و معدنی؛ آسیب‌پذیر در برابر نوسانات قیمت؛ کاهش قیمت، شوک‌های عظیم به اقتصاد وارد می‌کند؛ حمایت از بخش‌های تولیدی داخلی کم؛ واردات گسترده\n│ گروه دوم (صادرکننده کالای صنعتی) ⬅ اقتصاد مبتنی بر تولید و صدور کالاهای کارخانه‌ای و صنعتی با فناوری‌های پیشرفته و نوین\n│ اوپک (OPEC) ⬅ سازمان کشورهای صادرکننده نفت؛ کارتل بین‌المللی؛ ۱۱ کشور عضو: الجزایر، کنگو، گینه استوایی، گابن، ایران، عراق، کویت، لیبی، نیجریه، عربستان سعودی، ونزوئلا؛ تأسیس ۱۹۶۰؛ مقر وین؛ هدف: دفاع از منافع کشورهای صادرکننده نفت و فروش نفت با بهترین قیمت\n│ شاخص توسعه انسانی ⬅ درآمد و رفاه + امید به زندگی (متوسط طول عمر) + سواد و آموزش؛ عامل اول جنبه اقتصادی دارد\n│ مرکز ⬅ امریکای شمالی، اروپای غربی، ژاپن، استرالیا؛ صنایع نو و خدمات پیشرفته، فناوری بالا، نیروی ماهر و متخصص، زیرساخت مناسب، سطح بالای زندگی؛ مواد خام را ارزان می‌خرند و کالای ساخته‌شده را گران می‌فروشند؛ مغزهای متفکر را جذب می‌کنند\n│ پیرامون ⬅ افغانستان، بنگلادش، مراکش، نامبیا، پرو، نیکاراگوئه؛ صادرکننده مواد اولیه و خام؛ فناوری پایین‌تر؛ وابسته به واردات کالای صنعتی؛ کمبود نیروی ماهر و زیرساخت\n│ نیمه پیرامون ⬅ چین، کره جنوبی، سنگاپور؛ بین مرکز و پیرامون؛ از پیرامون قوی‌تر اما به مرکز نرسیده؛ نقش واسطه؛ جایگاه کشورها ثابت نیست و ممکن است تغییر کند\n└── نتیجه: نابرابری اقتصادی، در فضای جغرافیایی هم دیده می‌شود ──┘",
                    memoryTrick = "قلاب حافظه «دو گروه و مرکز-پیرامون»: دو گروه را قفل کن — «خام! صنعتی!»؛ گروه اول مواد خام صادر می‌کند و در برابر نوسان قیمت آسیب‌پذیر است، گروه دوم کالای صنعتی صادر می‌کند؛ سه جایگاه هم «مرکز! پیرامون! نیمه پیرامون!» است؛ مرکز یعنی امریکای شمالی و اروپا و ژاپن و استرالیا، پیرامون یعنی افغانستان و بنگلادش و مراکش و نامبیا و پرو و نیکاراگوئه، نیمه پیرامون یعنی چین و کره جنوبی و سنگاپور؛ اوپک هم «۱۱ کشور، ۱۹۶۰، وین» است."
